"""Byte-range download service (single range only).

Implements the behavior described in README.md:

- No Range header:        200, full body, Content-Length = length.
- One valid, satisfiable range:
                         206, Content-Range: bytes <start>-<end>/<length>,
                         Content-Length = length of the returned body.
  Ranges are inclusive of the end; an end past EOF is clamped;
  bytes=-N means the last N bytes.
- Range with start beyond EOF, zero suffix, reverse bounds, bad syntax,
  or any range on empty data:
                         416, empty body, Content-Range: bytes */<length>.
"""

from .ranges import parse_header


def serve(data, range_header=None):
    if range_header is None:
        return 200, {'Content-Length': str(len(data))}, data

    length = len(data)
    try:
        kind, a, b = parse_header(range_header)
    except (TypeError, ValueError):
        return _not_satisfiable(length)

    if kind == 'both':      # bytes=D-D (end inclusive, clamped at EOF-1)
        start, end = a, b
        if start >= length:          # start beyond EOF
            return _not_satisfiable(length)
        if end >= length:            # clamp an end past EOF
            end = length - 1
        if start > end:              # reverse bounds
            return _not_satisfiable(length)
    elif kind == 'prefix':  # bytes=D-
        start = a
        if start >= length:          # start beyond EOF (incl. empty data)
            return _not_satisfiable(length)
        end = length - 1
    else:                    # bytes=-D (suffix)
        if a == 0:                  # zero suffix
            return _not_satisfiable(length)
        start = length - a
        if start < 0:               # suffix longer than the data
            start = 0
        end = length - 1
        if start > end:             # guarantees 416 on empty data
            return _not_satisfiable(length)

    body = data[start:end + 1]
    return (
        206,
        {
            'Content-Length': str(len(body)),
            'Content-Range': 'bytes %d-%d/%d' % (start, end, length),
        },
        body,
    )


def _not_satisfiable(length):
    return (
        416,
        {
            'Content-Length': '0',
            'Content-Range': 'bytes */%d' % length,
        },
        b'',
    )
